import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BFzNpupd.js";const p=JSON.parse('{"title":"Architecture & Code Standards","description":"","frontmatter":{},"headers":[],"relativePath":"standards/01_ARCHITECTURE_AND_CODE_STANDARDS.md","filePath":"standards/01_ARCHITECTURE_AND_CODE_STANDARDS.md"}'),n={name:"standards/01_ARCHITECTURE_AND_CODE_STANDARDS.md"};function s(r,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture-code-standards" tabindex="-1">Architecture &amp; Code Standards <a class="header-anchor" href="#architecture-code-standards" aria-label="Permalink to &quot;Architecture &amp; Code Standards&quot;">​</a></h1><p>These guidelines define the structural rules and engineering standards for the <strong>Veg Sahayyak SDK</strong> codebase. AI agents and developers must adhere to these standards to maintain a clean, testable, and scalable modular architecture.</p><hr><h2 id="_1-modular-architecture-boundaries" tabindex="-1">1. Modular Architecture Boundaries <a class="header-anchor" href="#_1-modular-architecture-boundaries" aria-label="Permalink to &quot;1. Modular Architecture Boundaries&quot;">​</a></h2><p>The repository is organized into distinct Gradle modules with strict boundaries:</p><ul><li><strong><code>:speed-core</code> (Headless Telematics Engine)</strong><ul><li><strong>Responsibility:</strong> Mathematical signal processing (<code>TelematicsEngine</code>), Fused Location polling (<code>SpeedWatcher</code>), <code>SpeedColorScheme</code>, and foreground service lifecycle (<code>SpeedometerService</code>).</li><li><strong>Rules:</strong> <strong>CRITICAL:</strong> Jetpack Compose dependencies (e.g., <code>androidx.compose.ui</code>) must <strong>never</strong> leak into <code>:speed-core</code>. Minimal third-party footprint (only Google Play Services Location and Coroutines). Does not force DI frameworks on consuming clients.</li></ul></li><li><strong><code>:speed-ui</code> (Jetpack Compose Visual Layer)</strong><ul><li><strong>Responsibility:</strong> Hardware-accelerated canvas speedometer (<code>SpeedGauge</code>), HUD digital display (<code>HudDisplay</code>), windshield reflection modifiers (<code>Modifier.hudMirror</code>), accessibility semantics, and automotive themes (<code>SpeedUiColorScheme</code>).</li><li><strong>Rules:</strong> Depends on <code>:speed-core</code> and Jetpack Compose. No direct Android framework storage or location polling.</li></ul></li><li><strong><code>:speed-overlay</code> (Floating PiP Overlay Widget)</strong><ul><li><strong>Responsibility:</strong> Lightweight floating Picture-in-Picture window (<code>PipWidget</code>) for persistent speed display over third-party navigation apps.</li><li><strong>Rules:</strong> Optional plugin module. Decoupled from core logic.</li></ul></li><li><strong><code>:speed-autostart</code> (Zero-Touch Autostart Plugin)</strong><ul><li><strong>Responsibility:</strong> Background trip detection (<code>AutoStartManager</code>) via Google Play Activity Recognition (<code>IN_VEHICLE</code> transitions).</li><li><strong>Rules:</strong> Optional plugin module. Zero runtime overhead for clients not needing automatic drive detection.</li></ul></li><li><strong><code>:speed-bom</code> (Bill of Materials)</strong><ul><li><strong>Responsibility:</strong> Gradle platform artifact enforcing version alignment across SDK modules.</li></ul></li><li><strong><code>:app</code> (Sample / Demo Application)</strong><ul><li><strong>Responsibility:</strong> End-to-end integration demo showing <code>SpeedAssistant</code> usage in real-world Activity, Compose, and Hilt environments.</li></ul></li></ul><hr><h2 id="_2-dependency-injection-strategy" tabindex="-1">2. Dependency Injection Strategy <a class="header-anchor" href="#_2-dependency-injection-strategy" aria-label="Permalink to &quot;2. Dependency Injection Strategy&quot;">​</a></h2><ul><li><strong>SDK Modules (<code>:speed-core</code>, <code>:speed-ui</code>)</strong>: <ul><li>Employs a lightweight internal service locator (<code>SpeedCoreInternal</code>) to avoid imposing heavy DI frameworks on consuming clients.</li><li>Public interfaces (<code>ISpeedRepository</code>, <code>IPreferenceRepository</code>) can be overridden at runtime via <code>SpeedAssistant.useRepository()</code> or <code>SpeedAssistant.usePreferenceRepository()</code>.</li></ul></li><li><strong>Sample App (<code>:app</code>)</strong>: <ul><li>Hilt is used for sample app dependency injection.</li><li>Test modules use <code>@TestInstallIn</code> to bind test doubles (e.g. <code>FakeSpeedRepository</code>).</li></ul></li></ul><hr><h2 id="_3-ui-framework-jetpack-compose" tabindex="-1">3. UI Framework: Jetpack Compose <a class="header-anchor" href="#_3-ui-framework-jetpack-compose" aria-label="Permalink to &quot;3. UI Framework: Jetpack Compose&quot;">​</a></h2><ul><li><strong>New Features:</strong> All new UI must be written in <strong>Jetpack Compose</strong>.</li><li><strong>Canvas Rendering:</strong> Automotive gauges must use hardware-accelerated Compose Canvas drawing with precomputed trigonometric lookup tables and tokens.</li><li><strong>State Hoisting:</strong> UIs should be stateless. Hoist state to callers using <code>StateFlow&lt;SpeedData&gt;</code>.</li><li><strong>Naming:</strong> Composable functions must be PascalCase and annotated with <code>@Composable</code> (e.g., <code>SpeedGauge</code>, <code>GaugeNeedle</code>).</li></ul><hr><h2 id="_4-state-management-concurrency" tabindex="-1">4. State Management &amp; Concurrency <a class="header-anchor" href="#_4-state-management-concurrency" aria-label="Permalink to &quot;4. State Management &amp; Concurrency&quot;">​</a></h2><ul><li>Use <strong>Kotlin Coroutines</strong> and <strong>Flows</strong>.</li><li>Expose state streams using <code>Flow&lt;SpeedData&gt;</code> or <code>StateFlow</code>.</li><li>Thread boundary rules: <ul><li>Location event handling and mathematical filtering run on <code>Dispatchers.Default</code>.</li><li>Service lifecycle and notification updates run on <code>Dispatchers.Main.immediate</code>.</li></ul></li></ul><hr><h2 id="_5-coding-conventions" tabindex="-1">5. Coding Conventions <a class="header-anchor" href="#_5-coding-conventions" aria-label="Permalink to &quot;5. Coding Conventions&quot;">​</a></h2><ul><li><strong>Language:</strong> Kotlin only (Kotlin 1.9+ / 2.0+).</li><li><strong>Formatting:</strong> Adhere to standard ktlint and detekt guidelines.</li><li><strong>Null Safety:</strong> Avoid <code>!!</code> (not-null assertions). Use safe calls (<code>?.</code>) or Elvis operators (<code>?:</code>).</li><li><strong>Data Classes:</strong> Use <code>data class</code> for immutable state models (<code>SpeedData.SpeedChanged</code>, <code>TelematicsResult</code>).</li><li><strong>Early-Exits (Guard Clauses):</strong> Return early in validation logic instead of deeply nesting code inside <code>if</code> statements.</li><li><strong>DRY &amp; KISS:</strong> Extract repeated mathematical conversions into <code>SpeedUnit</code> and domain extensions.</li><li><strong>Meaningful KDoc:</strong> Document mathematical constants (e.g., alpha EMA factor, Schmitt trigger delta values) and unit expectations on all public APIs.</li></ul>',18)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
